type IconBadgeVisualEffect =
  | 'outline-lighting'
  | 'run-outline-lighting'
  | 'none'


/** 拿來當按鈕的icon, 有badge功能, 也有處理click邏輯 (包括disable跟pointerdown事件) */
@Component({
  selector: 'ap-icon-badge',
  standalone: true,
  imports: [ApIconBadgeCircleComponent],
  templateUrl: './ap-icon-badge.component.html',
  styleUrl: './ap-icon-badge.component.css',
})
export class ApIconBadgeComponent implements OnDestroy {
  readonly hasBadge = input<boolean>(false);
  readonly badgeTop = input<'top-0' | 'top-2'>('top-0');
  readonly disabled = input<boolean>(false);
  readonly disabledCoverVariant = input<'full' | 'half'>('full');
  readonly visualEffect = input<IconBadgeVisualEffect>('none');

  buttonClick = output<void>();

  constructor() {

  }

  ngOnDestroy(): void {
    
  }

}
